/**
 * Drift guard for the LobeHub marketplace manifest.
 *
 * `lhm.plugin.json` is the manifest the LobeHub Marketplace reads from the
 * repository. It is generated by connecting to the running server and reading
 * its tools, so it must always describe the server that is actually shipped.
 *
 * This test spawns the built server, reads the canonical `tools/list`, and
 * compares it with the committed manifest. A change to a tool name, a
 * description, or an input/output schema that is not mirrored in the manifest
 * fails here instead of silently reaching the marketplace.
 */

import { describe, it, before, after } from "node:test";
import assert from "node:assert";
import { spawn, type ChildProcess } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

const REPO_ROOT = path.resolve(".");
const MANIFEST_PATH = path.join(REPO_ROOT, "lhm.plugin.json");
const EXPECTED_IDENTIFIER = "reeinharddd-snapmcp";
const EXPECTED_TOOL_NAMES = [
  "capture_batch",
  "capture_browser",
  "capture_code",
  "capture_diff",
  "capture_document",
  "capture_file",
  "capture_gif",
  "capture_html",
  "capture_markdown",
  "capture_pdf",
  "capture_sequence",
  "capture_terminal",
  "snapmcp-hint",
].sort();

interface JsonRpcResponse {
  result?: {
    tools?: Array<{
      name: string;
      description?: string;
      inputSchema?: unknown;
      outputSchema?: unknown;
    }>;
    resources?: Array<{ name: string; uri: string; description?: string }>;
    prompts?: Array<{ name: string }>;
  };
}

/** Spawns the built server and collects one JSON-RPC response. */
class Server {
  private proc: ChildProcess;
  private idCounter = 0;
  private stdout = "";
  private stderr = "";
  private pending = new Map<number, (response: JsonRpcResponse) => void>();

  constructor(tmpDir: string) {
    this.proc = spawn("node", ["dist/index.js"], {
      cwd: REPO_ROOT,
      env: {
        ...process.env,
        SNAPMCP_DIR: tmpDir,
        SNAPMCP_LOG_LEVEL: "error",
        SNAPMCP_SECURITY_CHECKS: "true",
      },
      stdio: ["pipe", "pipe", "pipe"],
    });

    this.proc.stdout.on("data", (chunk: Buffer) => {
      this.stdout += chunk.toString();
      let index: number;
      while ((index = this.stdout.indexOf("\n")) !== -1) {
        const line = this.stdout.slice(0, index).trim();
        this.stdout = this.stdout.slice(index + 1);
        if (!line) continue;
        let message: { id?: number };
        try {
          message = JSON.parse(line);
        } catch {
          continue;
        }
        if (message.id && this.pending.has(message.id)) {
          this.pending.get(message.id)!(message as JsonRpcResponse);
          this.pending.delete(message.id);
        }
      }
    });

    this.proc.stderr.on("data", (chunk: Buffer) => {
      this.stderr += chunk.toString();
    });
  }

  async send(method: string, params?: unknown): Promise<JsonRpcResponse> {
    const id = ++this.idCounter;
    const promise = new Promise<JsonRpcResponse>((resolve) => {
      this.pending.set(id, resolve);
    });
    this.proc.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", id, method, params })}\n`);
    const timeout = new Promise<never>((_, reject) =>
      setTimeout(() => reject(new Error(`Timeout waiting for ${method}\n${this.stderr}`)), 20_000),
    );
    return Promise.race([promise, timeout]);
  }

  notify(method: string, params?: unknown): void {
    this.proc.stdin.write(`${JSON.stringify({ jsonrpc: "2.0", method, params })}\n`);
  }

  async stop(): Promise<void> {
    this.proc.kill("SIGTERM");
  }
}

/** Stable JSON with sorted object keys, so key order never fails a comparison. */
function stable(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(stable);
  if (value && typeof value === "object") {
    return Object.keys(value as Record<string, unknown>)
      .sort()
      .reduce<Record<string, unknown>>((acc, key) => {
        acc[key] = stable((value as Record<string, unknown>)[key]);
        return acc;
      }, {});
  }
  return value;
}

describe("LobeHub marketplace manifest", () => {
  let manifest: {
    identifier: string;
    name: string;
    version: string;
    author: string;
    description: string;
    tags: string[];
    prompts: unknown[];
    resources: Array<{ name: string; uri: string; description?: string }>;
    tools: Array<{
      name: string;
      description?: string;
      inputSchema?: unknown;
      outputSchema?: unknown;
    }>;
  };
  let server: Server;
  let tmpDir: string;

  before(async () => {
    manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf8"));
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "snapmcp-lhm-manifest-"));
    server = new Server(tmpDir);
    await server.send("initialize", {
      protocolVersion: "2025-06-18",
      capabilities: {},
      clientInfo: { name: "lhm-manifest-test", version: "1.0.0" },
    });
    server.notify("notifications/initialized");
  }, { timeout: 40_000 });

  after(async () => {
    if (server) await server.stop();
    if (tmpDir) {
      try {
        fs.rmSync(tmpDir, { recursive: true, force: true });
      } catch {
        /* best effort */
      }
    }
  }, { timeout: 15_000 });

  it("declares the marketplace identity and the current release version", () => {
    const pkg = JSON.parse(fs.readFileSync(path.join(REPO_ROOT, "package.json"), "utf8"));
    assert.equal(manifest.identifier, EXPECTED_IDENTIFIER);
    assert.equal(manifest.author, "reeinharddd");
    assert.equal(manifest.version, pkg.version, "The manifest version must match package.json");
    assert.ok(manifest.description.trim());
    assert.ok(manifest.tags.length > 0);
  });

  it("carries no machine-specific paths", () => {
    const raw = fs.readFileSync(MANIFEST_PATH, "utf8");
    assert.ok(!raw.includes(REPO_ROOT), "The manifest must not contain absolute local paths");
    assert.ok(!raw.includes("/home/"), "The manifest must not contain absolute local paths");
  });

  it("matches the tools the server actually serves", async () => {
    const listed = await server.send("tools/list");
    const live = listed.result?.tools ?? [];
    assert.equal(live.length, 13, "The server must expose exactly 13 tools");

    const declaredNames = manifest.tools.map((tool) => tool.name).sort();
    assert.deepEqual(declaredNames, EXPECTED_TOOL_NAMES);
    assert.deepEqual(live.map((tool) => tool.name).sort(), EXPECTED_TOOL_NAMES);

    for (const tool of live) {
      const declared = manifest.tools.find((entry) => entry.name === tool.name);
      assert.ok(declared, `The manifest must declare ${tool.name}`);
      assert.equal(
        declared.description,
        tool.description,
        `${tool.name} has a different description in the manifest`,
      );
      assert.deepEqual(
        stable(declared.inputSchema),
        stable(tool.inputSchema),
        `${tool.name} has a different input schema in the manifest`,
      );
      assert.deepEqual(
        stable(declared.outputSchema),
        stable(tool.outputSchema),
        `${tool.name} has a different output schema in the manifest`,
      );
    }
  }, { timeout: 30_000 });

  it("declares an output schema for every tool", () => {
    for (const tool of manifest.tools) {
      assert.ok(tool.outputSchema, `${tool.name} must declare an output schema`);
      assert.ok(tool.inputSchema, `${tool.name} must declare an input schema`);
    }
  });
});
